import json
from pathlib import Path
B=Path(__file__).parent
P=json.loads((B/'tile_plans.json').read_text()); S=json.loads((B/'screens.json').read_text()); G=json.loads((B/'inputs/path_glossary_bundle.json').read_text()); R=json.loads((B/'scenario_asset_registry.json').read_text())
g={x['context']['concept_id']:x for x in G['bundles']}
assets={a['asset_id']:a for a in R['assets']}
def records(a):
 a=assets[a];return [dict(zip([c['name'] for c in a['columns']],r)) for r in a['rows']]
def evidence(a): return json.dumps(records(a),indent=2)
def trial_summary():
 keys=['batch_size','peak_allocated_tensor_bytes','budget_bytes','completed_examples','elapsed_seconds','minimum_throughput','completed']
 rows=records('ds.batch_size_trials')
 keys=[k for k in keys if k in rows[0]]
 return json.dumps([{k:r[k] for k in keys} for r in rows],indent=2)
walk={}
for t in S['tiles']:
 for st in t['steps']:
  for bl in st.get('blocks',[]):
   if bl['type']=='code_walkthrough':walk[st['concept_ids'][0]]=bl['code']
# Each authored case includes its evidence-supported verdict and explanation.
# Answer ids are generated from that metadata, never copied into a separate key.
checks={}
def check(c,p,right,wrong1,why1,wrong2,why2):checks.setdefault(c,[]).append((p,[(right,True,'This follows the declared contract.'),(wrong1,False,why1),(wrong2,False,why2)]))
check('mle.pytorch_input_tensors','A supplied target fixture has fewer observations than its feature fixture. Under ordinary non-optimized execution, which acceptance policy enforces the declared tensor contract?', 'Assert the required axes and common batch length; reject the failed predicate before returning the aligned tuple.', 'Return the tuple as long as conversion succeeds.', 'Conversion does not establish the required axes or common batch length.', 'Return the mismatched tuple if the individual target values look valid.', 'Permitted individual values do not repair row correspondence; the false alignment predicate must fail.')
check('mle.dataset_minibatch_loader','A dataset already returns each feature and its corresponding target together. The declared loader policy is shuffle=True. Which invariant must hold when iterating for features, targets in loader?', 'Each feature remains with its own target, although source order is not assumed.', 'Every batch position must match the same source position.', 'Shuffle is an order policy, not a promise of source-order positions.', 'Features and targets may be shuffled independently.', 'The loader must preserve the feature/target relationship within each item.')
check('mle.neural_model_definition','The supplied task requires one unconstrained numerical output per observation. Which final-layer contract should be checked with a fixture batch?', 'One final linear output per observation, with no constraining final activation.', 'One final output followed by ReLU to force nonnegative predictions.', 'The supplied numerical-output contract is unconstrained; a final ReLU changes it.', 'One output for the entire batch, removing the observation axis.', 'The fixture must retain an output for each observation, not collapse the minibatch.')
check('mle.autograd_gradients','A fresh gradient comparison uses a matrix-shaped chain-rule reference and declared relative and absolute tolerances. Which assertion policy provides a defensible verdict?', 'Compare both parameter gradients with their matching references under both tolerances; the deliberately mismatched reference must fail.', 'Pass if only the total sum of the gradients matches.', 'A matching scalar sum does not establish agreement with a matrix-shaped reference.', 'Suppress the failed assertion and label the mismatched reference accepted.', 'A false predicate raises AssertionError; it cannot support an accepted verdict.')
check('mle.task_loss_selection','The supplied classification task uses class-index targets. Which CrossEntropyLoss input pair satisfies its declared contract?', 'Raw logits shaped (N, C) and long targets shaped (N,) with indices in [0, C).', 'Softmax probabilities shaped (N, C) and the same class indices.', 'The taught contract expects unnormalized logits, not probabilities substituted for them.', 'Raw logits shaped (N, C) and floating class indices shaped (N,).', 'The class-index target contract requires long indices, not floating indices.')
check('mle.task_loss_selection','The supplied binary task uses one logit and a target in [0, 1] per output element. Which input pair belongs in BCEWithLogitsLoss?', 'Raw logits and same-shaped binary targets in [0, 1].', 'Sigmoid-transformed probabilities and same-shaped binary targets.', 'BCEWithLogitsLoss already combines sigmoid with binary cross-entropy and expects logits.', 'Raw logits and targets with a different shape.', 'The supplied binary contract requires input and target tensors of the same shape.')
check('mle.optimizer_configuration','A plain-SGD test suite includes a valid update, a zero-learning-rate boundary and a deliberately incorrect expected update. Which verdict follows a false assert predicate during ordinary non-optimized execution?', 'The incorrect expectation raises AssertionError and is not accepted.', 'The false predicate is a warning and the test passes.', 'A false assert predicate raises AssertionError, not a pass-with-warning verdict.', 'The failed expectation is accepted because boundary fixtures are permitted.', 'An accepted boundary still satisfies its predicate; a deliberately false predicate does not.')
check('mle.minibatch_training_loop','The fixture uses plain SGD. Which predicate verifies that the recorded update has the intended magnitude and direction?', 'parameter_after - parameter_before agrees with -learning_rate * current_gradient under the declared tolerance.', 'Only the absolute magnitude of the change must match.', 'Magnitude alone does not verify the required direction of the plain-SGD update.', 'parameter_after - parameter_before agrees with +learning_rate * current_gradient.', 'Plain SGD subtracts the learning-rate-scaled current gradient; the positive sign reverses its direction.')
check('mle.training_evaluation_modes','A Dropout(p=0.5) fixture receives nonzero inputs. A training call retains every element. Which assertion policy handles this boundary correctly?', 'Accept if each output is either zero or twice its corresponding input; no element is required to be masked.', 'Reject every all-retained training call.', 'The taught masking/scaling rule permits an all-retained random outcome.', 'Accept arbitrary training outputs whenever no_grad is active.', 'no_grad does not change dropout behavior; outputs must still satisfy the masking/scaling rule.')
check('mle.weight_persistence','A checkpoint test has accepted, boundary and failed-reload fixtures. Which policy can issue a successful-reload verdict?', 'Issue success only when the declared assertions pass; a failed fixture must not receive success.', 'Catch AssertionError and return success for the failed fixture.', 'Catching a failed assertion does not make its predicate true.', 'Skip boundary assertions because boundary fixtures always pass.', 'Boundary cases must also satisfy the declared predicates; their label alone is not evidence.')
check('mle.validation_early_stopping','The team has training, validation and protected-test observations. Which data-access policy is valid when choosing early-stopping settings?', 'Use validation for the monitored decision and leave protected-test observations out of model and setting selection.', 'Use protected-test observations to choose patience, then call the test protected again.', 'Choosing settings using protected-test observations leaks information into the chosen system.', 'Fit preprocessing on protected-test observations while keeping them out of the loss.', 'Protected-test observations must not fit preprocessing either; excluding them only from the loss is insufficient.')
check('mle.training_failure_diagnosis','The declared diagnostic test includes a reproduced failure and a deliberately false predicate. Which handling preserves a meaningful assertion-based verdict?', 'Record the failure and require AssertionError for the deliberately false predicate during ordinary non-optimized execution.', 'Change the expected value until the reproduced failure passes.', 'Changing the expectation hides a false predicate instead of distinguishing the declared failure case.', 'Treat completion of the function as proof all predicates passed after suppressing AssertionError.', 'A suppressed false predicate is not a successful assertion-based verification.')
check('mle.device_placement','The actual result of torch.cuda.is_available() is False. Which selection follows the measured availability?', 'Select the supported CPU device.', 'Select cuda because the machine is advertised as accelerator-capable.', 'The measured availability check, not an advertised capability, governs this selection.', 'Select cuda and assume target tensors will make it available.', 'Tensor placement does not make an unavailable accelerator available; use the supported CPU fallback.')
check('mle.training_batch_sizing','For the trial evidence below, which selection rule applies the declared memory bound and performance requirement? The budget governs peak allocated tensor bytes, not total GPU usage.\n```json\n'+trial_summary()+'\n```', 'Consider completed trials within the allocated-tensor budget and performance requirement, then compare actual completed examples per elapsed time.', 'Choose the fastest trial even when its measured allocated peak exceeds the budget.', 'Performance does not override the declared measured memory bound.', 'Compare the allocated-tensor budget only with the input-byte estimate.', 'The supplied budget governs the allocated peak, not an input-only estimate or all GPU usage.')
check('mle.training_memory_diagnosis','A diagnostic history uses history.append(loss) on each backward-connected training loss; gradients through saved diagnostics are not needed. Which change addresses this retention risk?', 'Keep scalar or detached diagnostic values rather than graph-connected losses.', 'Keep the graph-connected losses and rely on their names being diagnostic.', 'A diagnostic label does not remove the tensor connection to its computation graph.', 'Copy the graph-connected losses into another list without detaching them.', 'Changing the containing list does not remove the graph connection of retained tensors.')
check('mle.training_bottleneck_profiling','A CPU clock records a CUDA call immediately after launch, with no synchronization. The run also includes first-use warm-up and profiler overhead. Which comparison is defensible?', 'Warm up first, synchronize timing boundaries and use a final unprofiled comparison of completed work.', 'Compare launch-return times as completed accelerator runtime.', 'Asynchronous CUDA launch-return time does not establish completed work without synchronization.', 'Treat a cold profiled run as final steady-state unprofiled timing.', 'Warm-up and profiler overhead must be handled before claiming a steady-state unprofiled comparison.')
check('mle.training_hardware_selection','Both authorized options have finished their bounded workloads. Which closure and billing record is required?', 'Stop both, wait and describe both to verify stopped states; retain lifecycle durations for compute billing and acknowledge possible continuing charges.', 'Stop only the selected option and calculate both bills from workload execution times.', 'Both options must be stopped and lifecycle-billed duration is not necessarily the bounded execution duration.', 'After stopping both, declare that all possible charges are zero.', 'Stopping ends compute billing but persistent disks and other charges can remain.')
check('ml.task_specific_pretrained_weight_fine_tuning','A review compares frozen pretrained and adapted predictions. Which policy supports a justified validation comparison and expected error cost?', 'Use the same validation cohort; compute FPR on actual negatives and FNR on actual positives, apply supplied deployment probabilities and error costs, and leave empty-group rates undefined without accessing protected test data.', 'Use FP divided by all validation observations for FPR and FN divided by all observations for FNR.', 'FPR and FNR condition on different actual-class groups, not on the whole cohort.', 'Tune on protected test data and report an empty conditioning group as zero error.', 'Protected-test tuning leaks information; an empty conditioning group does not define a zero rate.')

practices={}
def practice(c,context,cases):practices[c]=(context,cases)
def good(text,why):return (text,True,why)
def bad(text,why):return (text,False,why)
practice('mle.pytorch_input_tensors','Review independent converter submissions for the supplied row-corresponding accepted, boundary, three-target and incompatible-contract fixtures. Fixture contracts declare feature and target shapes and dtypes separately. Classify whether each excerpt enforces the named part of acceptance or silently accepts a failure.',[
 good(walk['mle.pytorch_input_tensors']+'\n# Apply the same failure-expectation harness to incompatible-contract fixtures.\nfor fixture in incompatible_contract_fixtures:\n    try:\n        prepare(**fixture)\n    except AssertionError:\n        pass\n    else:\n        raise AssertionError("Incompatible contract accepted")','Separate construction, dtype, shape and common-batch assertions precede tuple return; accepted/boundary fixtures run and incompatible fixtures must fail.'),
 good('for fixture in accepted_and_boundary_fixtures:\n    features, targets = prepare(**fixture)\n    assert isinstance((features, targets), tuple)\n    assert features.shape == fixture["feature_shape"]\n    assert targets.shape == fixture["target_shape"]\n    assert features.dtype == fixture["feature_dtype"]\n    assert targets.dtype == fixture["target_dtype"]\n    assert features.shape[0] == targets.shape[0]\n    # Supplied fixture provenance establishes matching observation order.','Accepted results are checked against their separately declared shapes and dtypes, including the boundary.'),
 bad('features = torch.from_numpy(features_array).to(dtype=feature_dtype)\ntargets = torch.from_numpy(targets_array).to(dtype=feature_dtype)\nreturn features, targets\n# The declared target dtype differs from feature_dtype.','Using feature dtype for targets violates the separate declared target representation and omits contract assertions.'),
 bad('features = torch.from_numpy(features_array)\ntargets = torch.from_numpy(three_target_array)\nassert features.shape[1] == declared_feature_width\nreturn features, targets\n# Features have the accepted fixture batch length; the target array is the supplied shorter failure.','Checking feature width alone does not reject the mismatched batch length.')])
practice('mle.dataset_minibatch_loader','Inspect dataset and loader checks for the supplied five indexed observations and both final-batch policies. In the snippets, expected_pairings and declared_boundary_sizes come from the supplied fixture; no execution is required.',[
 good(walk['mle.dataset_minibatch_loader'],'The dataset returns same-index tuples, reports the source count and checks observed batch boundaries for both drop policies.'),
 good('assert len(dataset) == len(feature_observations)\nfor index in range(len(dataset)):\n    assert dataset[index] == expected_pairings[index]\n# With shuffle=False, assert observed pairings equal expected_pairings in source order.\n# With shuffle=True, assert every observed pair belongs to expected_pairings and\n# all retained observation identities occur exactly as the declared drop policy requires.\n# Deliberately mismatched feature/target identity must raise AssertionError.','Identity checks distinguish source order from pair membership, cover both shuffle policies and reject the mismatched pairing.'),
 bad('def __getitem__(self, index):\n    return self.features[index], self.targets[(index + 1) % len(self.targets)]\n# Supplied observations have distinct identities.','The target comes from another observation even if dimensions still collate.'),
 bad('loader = DataLoader(dataset, batch_size=declared_size, shuffle=True)\n# Test insists every output position equals the same source position.','Source-position equality is not a valid expectation under shuffle=True.')])
practice('mle.neural_model_definition','The task is the supplied numerical-output model: registered linear layers with matching intermediate widths, ReLU between them and an unconstrained final output. Inspect these independent submissions against the fixture contract.',[
 good('import torch.nn as nn\nclass OrderModel(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.layers = nn.Sequential(nn.Linear(feature_width, hidden_width),\n                                    nn.ReLU(), nn.Linear(hidden_width, output_width))\n    def forward(self, x):\n        return self.layers(x)\ndef build_model():\n    return OrderModel()\nmodel = build_model()\nassert isinstance(model, nn.Module)\nassert model(fixture_features).shape == declared_output_shape','The module registers its composition, implements forward, matches widths and checks the required fixture output.'),
 bad('self.layers = nn.Sequential(nn.Linear(feature_width, hidden_width),\n                            nn.ReLU(), nn.Linear(other_width, output_width))\n# other_width differs from hidden_width.','The second linear input width does not match the preceding output width.'),
 bad('self.layers = nn.Sequential(nn.Linear(feature_width, hidden_width),\n                            nn.ReLU(), nn.Linear(hidden_width, output_width), nn.ReLU())','The final ReLU constrains outputs that the task requires to remain unconstrained.'),
 bad('class OrderModel(nn.Module):\n    def __init__(self):\n        super().__init__()\n        layers = nn.Linear(feature_width, output_width)\n    # No forward method is implemented.','Local construction without a registered layer attribute and an implemented forward does not meet the model-definition deliverable.')])
practice('mle.autograd_gradients','Inspect the gradient calculation and its verification. X, D, supplied leaf tensors, reduction convention and tolerances are fixture inputs. Classify evidence of a fresh, matrix-shaped comparison versus a defective verification.',[
 good(walk['mle.autograd_gradients'],'Fresh trainable leaves and cleared gradients feed backward; both matrix-shaped references retain the supplied reduction in D and are checked under explicit tolerances.'),
 good('# Apply the same gradient-comparison function to valid and boundary fixtures.\nfor fixture in valid_and_boundary_fixtures:\n    verify_gradients(**fixture)\n# Failure fixture changes only the supplied reference.\ntry:\n    verify_gradients(**mismatched_reference_fixture)\nexcept AssertionError:\n    pass\nelse:\n    raise AssertionError("Mismatched reference accepted")','The valid/boundary checks and explicitly rejected false reference preserve the assertion-based acceptance contract.'),
 bad('loss.backward()\n# Old W.grad and b.grad from a previous backward were never cleared.\nassert torch.allclose(W.grad, X.T @ D, rtol=rtol, atol=atol)','Backward accumulation makes this a comparison of accumulated, not fresh, gradients.'),
 bad('# D already includes the declared mean-loss reduction.\nreference_W = (X.T @ D) / batch_length\nreference_b = D.sum(dim=0) / batch_length','Dividing again changes the supplied chain-rule reference; the reduction is already in D.')])
practice('mle.task_loss_selection','Inspect the supplied same-shaped numerical-output fixture under mean MSE. The excerpts are independent checks of scalar objective and derivative direction; expected_loss and expected_output_derivatives are the declared fixture references.',[
 good('from torch import nn\nassert outputs.shape == targets.shape\noutputs.requires_grad_(True)\nloss = nn.MSELoss(reduction="mean")(outputs, targets)\nloss.backward()\nassert torch.allclose(loss, expected_loss, rtol=rtol, atol=atol)\nassert torch.allclose(outputs.grad, expected_output_derivatives, rtol=rtol, atol=atol)\nassert torch.all(outputs.grad > 0)\n# Both supplied outputs exceed their corresponding targets.','Equal shapes and mean MSE are verified against both scalar and derivative references; positive derivatives indicate increasing loss when those outputs increase.'),
 good('M = outputs.numel()\nreference = 2 * (outputs - targets) / M\nassert torch.allclose(reference, expected_output_derivatives, rtol=rtol, atol=atol)\n# Interpret a positive derivative as loss increasing for a positive output perturbation.','The derivative includes mean reduction over output elements and its sign is interpreted in the correct direction.'),
 bad('loss = nn.MSELoss(reduction="sum")(outputs, targets)\n# Report it as the declared mean-MSE objective.','Sum reduction does not satisfy the declared mean objective or its derivative reference.'),
 bad('reference = 2 * (targets - outputs) / outputs.numel()\n# Claim positive reference entries mean increasing outputs decreases loss.','The sign is reversed relative to the output derivative and the stated direction is wrong.')])
practice('mle.optimizer_configuration','The fixture uses plain SGD with no momentum, weight decay or other modifications. Inspect the current-update and zero-learning-rate checks under the declared tolerances; scalar values are supplied by the fixture.',[
 good('optimizer = torch.optim.SGD(model.parameters(), lr=learning_rate)\noptimizer.zero_grad()\nloss.backward()\nbefore = parameter.detach().clone()\ncurrent_gradient = parameter.grad.detach().clone()\noptimizer.step()\nassert torch.allclose(parameter.detach(), before - learning_rate * current_gradient, rtol=rtol, atol=atol)\nassert torch.allclose(parameter.detach() - before, -learning_rate * current_gradient, rtol=rtol, atol=atol)','The optimizer receives model parameters, uses the current gradient and checks both resulting value and signed change.'),
 good('# Separate boundary fixture supplies zero learning rate.\nupdated = run_plain_sgd(boundary_fixture)\nassert torch.allclose(updated, boundary_fixture.initial_parameter, rtol=rtol, atol=atol)\n# A deliberately incorrect expected update must raise AssertionError.','Zero rate leaves the parameter unchanged; a false expected update is not accepted.'),
 bad('optimizer.zero_grad()\nloss.backward()\noptimizer.step()\nassert torch.allclose(parameter.detach() - before, learning_rate * current_gradient, rtol=rtol, atol=atol)','The positive sign contradicts the plain-SGD subtraction equation.'),
 bad('loss.backward()\noptimizer.zero_grad()\noptimizer.step()\n# Claim the step used the current backward gradient.','Clearing after backward removes the current gradient before its intended update.')])
practice('mle.minibatch_training_loop','Review independent snippets from the bounded plain-SGD minibatch loop. The source has five observations and retains the incomplete final batch. Classify whether each snippet verifies its stated loop obligation.',[
 good(walk['mle.minibatch_training_loop'],'Each minibatch gets one current-gradient update with a signed-delta assertion and scalar loss plus actual count evidence.'),
 good('assert observed_batch_sizes == declared_boundary_sizes\nassert sum(observed_batch_sizes) == declared_observation_count\n# The supplied final incomplete batch is retained, not padded.\nfor fixture in valid_and_boundary_fixtures:\n    verify_loop(**fixture)\ntry:\n    assert declared_false_predicate\nexcept AssertionError:\n    pass\nelse:\n    raise AssertionError("False predicate accepted")','Actual counts verify the incomplete batch; accepted and boundary fixtures are tested and the false predicate is rejected.'),
 bad('optimizer.zero_grad()\nfor features, targets in loader:\n    loss = loss_fn(model(features), targets)\n    loss.backward()\n    optimizer.step()\n# Gradients are not cleared inside the minibatch loop.','Later updates accumulate earlier minibatch gradients instead of using only the intended current gradient.'),
 bad('for features, targets in loader:\n    batch_records.append((loss.item(), configured_batch_size))\n# configured_batch_size is used even for the retained incomplete final batch.','Reporting configured size instead of actual batch count invents observations in the final batch.')])
practice('mle.training_evaluation_modes','Inspect a Dropout(p=0.5) mode-sensitive fixture and its surrounding validation pass. Use the per-element masking/scaling rule, including the all-retained boundary, not a demand that every random call mask an element.',[
 good('model.eval()\nwith torch.no_grad():\n    predictions = model(x)\nassert torch.equal(dropout_layer_in_eval(x), x)\nassert predictions.requires_grad is False\n# No optimizer.step() occurs in validation.\nmodel.train()','Evaluation mode and disabled graph recording serve separate purposes; validation is forward-only and the fixture restores training.'),
 good('layer.train()\ntraining_output = layer(x)\nassert torch.all((training_output == 0) | (training_output == 2 * x))\n# The supplied all-retained boundary is checked by the same predicate.\ntry:\n    assert torch.all((invalid_output == 0) | (invalid_output == 2 * x))\nexcept AssertionError:\n    pass\nelse:\n    raise AssertionError("Invalid dropout outcome accepted")','The predicate accepts both masked and scaled retained elements, permits the all-retained boundary and rejects the supplied invalid result.'),
 bad('layer.train()\nwith torch.no_grad():\n    result = layer(x)\n# Claim result must equal x because no_grad puts dropout in evaluation mode.','no_grad disables graph recording but does not switch dropout into evaluation mode.'),
 bad('model.eval()\nloss = loss_fn(model(validation_features), validation_targets)\nloss.backward()\noptimizer.step()\n# Label this pass forward-only validation.','An optimizer step in validation violates the forward-only requirement.')])
practice('mle.weight_persistence','Inspect independent parts of a reload verifier. build_same_architecture constructs the supplied compatible architecture, fixture inputs are fixed, and rtol/atol are explicitly supplied. A successful verdict requires both parameter-state and prediction checks.',[
 good('model.eval()\nwith torch.no_grad():\n    original_predictions = model(fixture_inputs)\nwith open(path, "wb") as handle:\n    torch.save(model.state_dict(), handle)\nrestored = build_same_architecture()\nwith open(path, "rb") as handle:\n    mapping = torch.load(handle, weights_only=True)\nrestored.load_state_dict(mapping)\nrestored.eval()\nwith torch.no_grad():\n    restored_predictions = restored(fixture_inputs)\nassert torch.allclose(restored_predictions, original_predictions, rtol=rtol, atol=atol)\nfor name, value in model.state_dict().items():\n    assert torch.allclose(restored.state_dict()[name], value, rtol=rtol, atol=atol)','Binary handles, compatible architecture and safe parameter mapping restore the state; both corresponding entries and fixed-input evaluation predictions are compared.'),
 good('# Supplied unit tests call this verifier with valid and boundary checkpoints.\n# Failure fixtures include a deliberately changed state and a failed predicate.\n# They must not receive successful_reload=True; false assertions raise AssertionError.','Unit-test fixtures cover acceptance and boundary assertions without turning failed fixtures into successful reloads.'),
 bad('with open(path, "w") as handle:\n    torch.save(model.state_dict(), handle)\n# This is intended to satisfy the required binary-save protocol.','Text write mode is not the required binary handle protocol.'),
 bad('restored.load_state_dict(mapping)\n# Compare no state entries and no predictions.\nreturn {"successful_reload": True}','Loading alone does not establish the required state preservation and prediction agreement.')])
practice('mle.validation_early_stopping','Review the strict minimized-loss controller and its evidence. The trace below is the supplied read-only fixture, not a live training run. Classify policy-respecting evidence versus defective decisions.',[
 good(walk['mle.validation_early_stopping']+'\n# best_epoch is recorded inside the improvement branch and returned with best.','The bounded loop uses the strict threshold, counts non-improvements, breaks on patience and preserves a separate checkpoint without protected-test access.'),
 good('```json\n'+evidence('ds.early_stopping_trace')+'\n```\n# Restore the last accepted checkpoint in this trace and report its epoch and loss.','The trace shows the declared counter progression, patience exhaustion and retained accepted checkpoint rather than selecting the numerically lowest insufficient improvement.'),
 bad('if current < best:\n    best = current\n    non_improvements = 0\n    best_state = model.state_dict()\n# min_delta is declared positive; later training mutates model parameters.','Ignoring min_delta changes the improvement rule; a live state_dict reference does not independently preserve the best epoch.'),
 bad('current = loss_on_protected_test()\nif current < best - min_delta:\n    best_state = deepcopy(model.state_dict())','A correct threshold and snapshot do not excuse using protected-test observations for model selection.')])
practice('mle.training_failure_diagnosis','Review the reproduced numerical-training failure. The declared plain-SGD fixture has compatible output/target shapes and learning rate but its current update has the wrong sign. The failing reference records nonzero expected parameter gradients. Decide whether each excerpt supports the single-cause diagnosis and verification.',[
 good('loss.backward()\nrecord = {"loss": loss.item(), "output_shape": predictions.shape,\n          "target_shape": targets.shape, "learning_rate": learning_rate,\n          "gradients": [p.grad.detach().clone() for p in model.parameters()]}\n# Record is captured before any zero_grad call.\n# Compare loss-to-output derivatives, parameter-gradient signs and magnitudes\n# with the supplied references; preserve this same fixture and failing record.','Gradients are captured while the signal is available and checked through the derivative chain alongside loss, shape and rate evidence.'),
 good('# Reproduce the positive-sign update failure with the original fixture.\n# Change only the update sign to the declared plain-SGD subtraction.\nassert torch.allclose(after - before, -learning_rate * current_gradient, rtol=rtol, atol=atol)\nassert torch.allclose(corrected_gradients, expected_gradients, rtol=rtol, atol=atol)\nassert declared_loss_expectation(corrected_loss)\n# Run valid and boundary assertions; the deliberately false predicate must raise AssertionError.','One evidence-supported sign correction is tested on the same fixture against update, loss and gradient expectations with accepted and failure cases.'),
 bad('loss.backward()\noptimizer.zero_grad()\nrecorded_gradients = [p.grad for p in model.parameters()]\n# Infer that the expected parameters never received a gradient.','Inspection after clearing cannot establish whether backward delivered the required learning signal.'),
 bad('# Change the learning rate, task loss and fixture observations together.\n# Report the new loss without comparing with the reproduced failing reference.','Multiple changes and a different fixture do not test a single root-cause hypothesis.')])
practice('mle.device_placement','These are authored review excerpts, not commands to execute. INSTANCE and ZONE denote only the already authorized supplied instance. Review lifecycle identity, measured device placement, bounded execution and failure checks.',[
 good('gcloud compute instances describe INSTANCE --zone=ZONE\n# Inspect authorized identity and initial stopped state.\ngcloud compute instances start INSTANCE --zone=ZONE\n# Wait for completion; describe and verify running state.\ngcloud compute ssh INSTANCE --zone=ZONE\n# Execute only the bounded fixture.\ngcloud compute instances stop INSTANCE --zone=ZONE\n# Wait for completion; describe the same identity and verify final TERMINATED state.','The record checks the authorized identity, initial/running/final states and verified shutdown after bounded work.'),
 good('device = torch.device("cuda" if torch.cuda.is_available() else "cpu")\nmodel.to(device)\nfeatures = features.to(device)\ntargets = targets.to(device)\nrecorded_devices = ([p.device for p in model.parameters()], features.device, targets.device)\nassert all(p.device == features.device == targets.device for p in model.parameters())\nloss = loss_fn(model(features), targets)\nloss.backward()\nwith torch.no_grad():\n    predictions = model(features)\n# No additional device transfers occur during this bounded fixture.\n# Valid and CPU-boundary placement predicates pass; the supplied false predicate raises AssertionError.','Measured selection and a single compatible placement support forward/backward and prediction checks with boundary and failure assertions.'),
 bad('model.to(device)\nfeatures = features.to(device)\n# Targets remain on CPU although device is cuda.\nloss = loss_fn(model(features), targets)','Model, input and targets are not compatibly placed for the declared computation.'),
 bad('gcloud compute instances stop INSTANCE --zone=ZONE\n# Mark final_stopped=True immediately, without waiting or describing the instance.','Requesting stop alone does not verify the completed resulting lifecycle state.')])
practice('mle.training_batch_sizing','Inspect controlled CUDA trial evidence and measurement code. Keep the budget scoped to allocated tensor bytes. Select eligibility using actual completed observations, including the incomplete final batch, rather than configured batch slots.',[
 good('```json\n'+evidence('ds.batch_size_trials')+'\n```\n# Select only completed, memory-eligible, performance-eligible trials.\n# Within that set compare completed_examples / elapsed_seconds.','The records preserve shapes, feature-plus-target estimates, reset/peak protocol, actual counts and measured eligibility, allowing selection without treating estimates as peak training usage.'),
 good('for batch_size in declared_trial_sizes:\n    loader = DataLoader(dataset, batch_size=batch_size, shuffle=fixed_shuffle, drop_last=False)\n    torch.cuda.reset_peak_memory_stats()\n    completed_examples = 0\n    # Workload, model, dtypes, alignment and timing protocol are otherwise fixed.\n    for features, targets in loader:\n        assert features.shape[0] == targets.shape[0]\n        bounded_training_step(features, targets)\n        completed_examples += features.shape[0]\n    peak = torch.cuda.max_memory_allocated()\n    input_estimate = batch_size * feature_columns * feature_element_bytes + batch_size * target_element_bytes\n    # Retain measured peak and estimate separately; synchronize elapsed-time boundaries.','Only batch size varies; actual counts include the partial batch and peak allocated storage is measured separately from the matrix estimate.'),
 bad('# Trial exceeds the declared allocated-tensor peak budget.\n# Select it because its input-plus-target estimate is below that budget.','An estimate below budget does not make an excessive measured allocated peak eligible.'),
 bad('completed_examples = number_of_batches * configured_batch_size\n# The final batch is incomplete and retained.','Multiplying by configured size overcounts the final partial batch and corrupts completed-work performance.')])
practice('mle.training_memory_diagnosis','Review a bounded failure reproduced with graph-connected losses retained only for diagnostics. The supplied evidence identifies failure while those graphs remain live. Classify whether each excerpt supports allocation accounting, one correction and same-workload verification.',[
 good('# Preserve failed-run peak_allocated, peak_reserved and failure_stage.\nweight_bytes = F * H * element_width\nbias_bytes = H * element_width\nparameter_bytes = weight_bytes + bias_bytes\ngradient_bytes = parameter_bytes\nactivation_bytes = batch_rows * H * element_width\ninput_bytes = batch_rows * F * element_width\n# Add targets and other simultaneously live matrices from the supplied inventory.\nreference = parameter_bytes + gradient_bytes + activation_bytes + input_bytes + target_bytes + other_live_bytes\n# Label allocated as tensor-occupied and reserved as caching-allocator-held storage.','Matrix element counts include weights, bias, gradients, activations and batches; reserved memory is distinguished from tensor-occupied memory.'),
 good('# Failing history retains loss tensors solely for diagnostics.\n# Single correction: replace graph-connected diagnostic retention with scalar loss.item() records.\n# Rerun the identical bounded task; retain completion, allocated and reserved peaks.\nassert corrected_completed\nassert corrected_peak_allocated <= supplied_allocated_budget\n# Return failing evidence, allocation reference, diagnosis, correction and corrected evidence.','The correction targets the reproduced retention cause and verifies completion against the same scoped requirement while retaining both measured peaks.'),
 bad('torch.cuda.empty_cache()\n# Keep all live graph-connected history tensors.\n# Claim empty_cache releases their occupied tensor storage.','empty_cache releases unused cached memory, not storage occupied by live tensors.'),
 bad('reference = batch_rows * F * element_width\n# Treat this input-only estimate as all simultaneously live training allocations.','The reference omits parameters, gradients, activations, targets and other live matrices needed to attribute exhaustion.')])
practice('mle.training_bottleneck_profiling','Review a trace whose labeled loading region dominates transfer and computation. Supporting container evidence identifies the loader process as CPU-limited, and the same bounded fixture reproduces that pattern. No live profiler or container is provided.',[
 good('with torch.profiler.profile(...) as prof:\n    with record_function("loading"):\n        features, targets = next_batch()\n    with record_function("transfer"):\n        move_batch()\n    with record_function("model computation"):\n        bounded_compute()\nprint(prof.key_averages().table(...))\n# Trace: loading dominates; transfer and model computation are smaller.\n# docker stats: loader CPU limit reached during that interval.\n# docker top: the expected loader process is running.\n# Repeated identical fixture reproduces the loading attribution.','Stage labels and trace attribution identify loading, while same-interval process/resource evidence corroborates rather than replaces timing evidence.'),
 good('# Change only the supplied loader CPU limit supported by the reproduced evidence.\n# Warm up both versions; compare identical completed work without profiling overhead.\n# Synchronize CUDA at both CPU-clock timing boundaries.\n# Record before/after elapsed time and report improvement only if the measured comparison supports it.','One supported loading correction is tested on the same bounded work with warm-up, overhead and completed CUDA work handled.'),
 bad('# Loading dominates the trace and the loader CPU limit is reached.\n# Conclude model computation is dominant solely because an accelerator exists.','Device presence is not evidence against the observed labeled-stage and process attribution.'),
 bad('# Change loader limit and model size together.\n# Report improvement from a cold profiled launch-only CUDA time.','Multiple changes, warm-up/profiler artifacts and uncompleted CUDA timing cannot verify the isolated bottleneck hypothesis.')])
practice('mle.training_hardware_selection','Review the matched CPU/accelerator options for the same bounded matrix workload. INSTANCE and ZONE remain authorized placeholders, not new resources. The evidence below retains compute execution and lifecycle billing scopes separately.',[
 good('```json\n'+evidence('ds.hardware_comparison')+'\n```\n# Verify completion, task quality, observed memory and elapsed time against all fixed limits.\n# Select only feasible options; keep execution_duration * supplied_rate separate\n# from lifecycle_duration * supplied_rate. Retain both verified stopped states.','Matched records retain placement, completion, quality, memory, timing, rates and shutdown; cost scope is not confused with utilization or execution duration.'),
 good('# For each already-authorized CPU and accelerator option:\ngcloud compute instances describe INSTANCE --zone=ZONE\n# Inspect identity and initial state.\ngcloud compute instances start INSTANCE --zone=ZONE\n# Wait, describe and verify running.\ngcloud compute ssh INSTANCE --zone=ZONE\n# Check accelerator availability where relevant; place model/features/targets together.\n# Run matched bounded work with declared warm-up and relevant movement included.\ngcloud compute instances stop INSTANCE --zone=ZONE\n# Wait, describe both options and verify TERMINATED.\n# Retain measured lifecycle durations and continuing disk/other-charge warning.','Both options are inspected, connected, benchmarked comparably and verifiably stopped, with lifecycle evidence retained.'),
 bad('# Select the quickest option without checking completion, task quality or memory limits.','Runtime alone does not establish feasible capacity under the fixed task and memory constraints.'),
 bad('# Both workload executions ended. Leave the non-selected VM running.\n# Bill both only for execution_seconds * rate and claim no continuing charges.','Both options must be stopped; lifecycle billing differs from execution cost and persistent charges may remain.')])
practice('ml.task_specific_pretrained_weight_fine_tuning','Inspect the bounded two-class ViT adaptation audit. Scaffolding supplies compatible checkpoint, label mappings, image datasets/collator, tolerances, counts and deployment costs. Judge each independent excerpt for its stated verification obligation, without running transformers or accessing protected-test observations.',[
 good('import torch\nfrom torch import nn\nfrom transformers import AutoImageProcessor, ViTForImageClassification, TrainingArguments, Trainer\nmodel = ViTForImageClassification.from_pretrained(checkpoint)\nprocessor = AutoImageProcessor.from_pretrained(checkpoint)\noriginal_mapping = dict(model.config.id2label)\ninputs = processor(validation_images, return_tensors="pt")\n# Retain frozen baseline logits and original mapping before replacing classifier.\nbaseline_logits = model(**inputs).logits.detach().clone()\n# Training/validation images use this same processor; protected test is never accessed.','The baseline is retained before replacement under its original mapping and uses the matched checkpoint processor and validation cohort.'),
 good('for parameter in model.parameters():\n    parameter.requires_grad = False\nmodel.classifier = nn.Linear(model.config.hidden_size, num_labels)\nmodel.num_labels = model.config.num_labels = num_labels\nmodel.config.id2label = id2label\nmodel.config.label2id = label2id\n# Snapshot head and backbone values before training.\nargs = TrainingArguments(output_dir=output_dir, num_train_epochs=epochs, per_device_train_batch_size=batch_size, learning_rate=learning_rate, eval_strategy="epoch", remove_unused_columns=False)\ntrainer = Trainer(model=model, args=args, train_dataset=train_dataset, eval_dataset=validation_dataset, data_collator=data_collator, processing_class=processor)\ntrainer.train()\nassert head_values_changed\nassert frozen_backbone_values_unchanged','The backbone is frozen before constructing a trainable new head; the bounded supervised run checks changed head and unchanged frozen values.'),
 good('assert logits.shape == (N, C)\nassert targets.shape == (N,)\nassert targets.dtype == torch.long\nassert torch.all((targets >= 0) & (targets < C))\nassert C == len(id2label)\nloss = task_loss(logits, targets)\nloss.backward()\nreference_W = head_inputs.T @ D\nassert torch.allclose(selected_head_gradient, selected_reference_from(reference_W), rtol=rtol, atol=atol)\n# D is the declared scalar-task-loss derivative including reduction.','Task label shape and range match output width; backward and a selected chain-rule comparison provide evidence of the intended head learning signal.'),
 good('def compare_counts(counts):\n    FP, TN, FN, TP = counts\n    fpr = FP / (FP + TN) if FP + TN else None\n    fnr = FN / (FN + TP) if FN + TP else None\n    cost = None if fpr is None or fnr is None else p0 * fpr * cost_FP + p1 * fnr * cost_FN\n    return fpr, fnr, cost\n# Return these comparisons for baseline and adapted predictions on the SAME validation cohort.\n# If defined, justify improvement only from lower expected cost under supplied costs/probabilities;\n# report non-improvement or undefined comparison otherwise. No protected-test access.','Both conditional rates and probability-weighted expected costs use the correct conditioning groups, leave empty groups undefined and support a matched non-leaking conclusion.'),
 bad('for parameter in model.parameters():\n    parameter.requires_grad = True\ntrainer.train()\n# Claim classifier-only adaptation because the classifier changed.','Changed head values alone do not prove classifier-only training when the backbone is also trainable.'),
 bad('chosen_settings = tune_on(protected_test_images)\nfpr = FP / total_validation_count\nfnr = FN / total_validation_count\n# Replace empty actual-class rates with zero and claim improvement.','Protected-test tuning leaks information, total-cohort denominators are not conditional rates and an empty group has no defined rate.')])

# Bind numerical fixture context directly to the taught source examples.
for cid in ['mle.task_loss_selection','mle.optimizer_configuration','mle.neural_model_definition']:
 context,cases=practices[cid]
 if cid=='mle.task_loss_selection':
  source=next(x['content'] for x in g[cid]['teaching_blocks'] if 'outputs [2, 4]' in x['content']).split(' For a binary-logit fixture')[0]
 else:
  source=g[cid]['practice_anchor']['success']
 practices[cid]=(context+' Supplied fixture contract: '+source,cases)

out={k:P[k] for k in ['schema_version','path_id','batch_id']};out['kind']='interactions_part';out['tiles']=[]
for ti,t in enumerate(P['tiles']):
 rows=[];first=set();cursor={};interaction_steps=[s for s in t['steps'] if s['type'] in ('check','hands_on')]
 for pos,st in enumerate(interaction_steps):
  cid=st['concept_ids'][0];bundle=g[cid]
  measures=[]
  for a in st['anchors']:
   if '#assessment:' in a:
    cap=a.split('#assessment:')[1];anchor=next(x for x in bundle['assessment_anchors'] if x['capability']==cap)
    measures.append({'concept_id':cid,'capability':cap,'fact_ids':anchor['fact_ids']})
  difficulty='intro' if pos==0 else ('stretch' if pos==len(interaction_steps)-1 else 'core')
  ix={'type':st['planned_interaction_type'],'interaction_id':'ix.'+st['step_id'],'difficulty':difficulty,'grading_mode':'client','standalone':True,'measures':measures,'anchors':st['anchors']}
  if st['type']=='check':
   n=cursor.get(cid,0);cursor[cid]=n+1;prompt,options=checks[cid][n]
   # Vary the correct position deterministically without leaking it in feedback or labels.
   shift=(ti+pos)%len(options);options=options[shift:]+options[:shift]
   public_options=[{'option_id':f'o{i+1}','text':v[0]} for i,v in enumerate(options)]
   ix['public']={'prompt':prompt,'options':public_options,'selection':'single','shuffle':True}
   ix['grading']={'correct_option_ids':[public_options[i]['option_id'] for i,v in enumerate(options) if v[1]],'option_feedback':{public_options[i]['option_id']:{'message':v[2]} for i,v in enumerate(options)}}
  else:
   context,cases=practices[cid]
   supported=[v for v in cases if v[1]]; defective=[v for v in cases if not v[1]]
   cases=[]
   while supported or defective:
    if defective: cases.append(defective.pop(0))
    if supported: cases.append(supported.pop(0))
   shift=(ti+pos)%len(cases);cases=cases[shift:]+cases[:shift]
   items=[{'item_id':f'i{i+1}','text':text} for i,(text,ok,why) in enumerate(cases)]
   ix['public']={'prompt':context+' Sort every excerpt into the two buckets. Judge only the obligation stated in the excerpt, not missing surrounding scaffolding.','buckets':[{'bucket_id':'supported','label':'Supports the stated verification obligation'},{'bucket_id':'defective','label':'Violates the stated verification obligation'}],'items':items}
   ix['grading']={'assignments':{items[i]['item_id']:'supported' if v[1] else 'defective' for i,v in enumerate(cases)},'role_map':{'supported':'supported verification','defective':'contract violation'},'item_feedback':{items[i]['item_id']:{'message':v[2]} for i,v in enumerate(cases)}}
  facts={x['id']:x['statement'] for x in bundle['coverage']['required_facts']}
  tested=[facts[f] for m in measures for f in m['fact_ids']]
  ix['feedback']={'correct':{'message':'The verdict follows the declared contract and the supplied evidence.'},'incorrect':{'message':'Recheck the contract and the specific failed predicate or policy; use the per-item explanation to locate the defect.'},'hints':['Separate the stated acceptance condition from evidence that merely shows an operation was attempted.']}
  if cid not in first:
   rem=next((r['step_id'] for r in next(x for x in S['tiles'] if x['tile_id']==t['tile_id']).get('remediation_steps',[]) if cid in r['concept_ids']),None)
   if rem:ix['feedback']['remediation_step_id']=rem
   first.add(cid)
  rows.append({'step_id':st['step_id'],'interaction':ix})
 out['tiles'].append({'tile_id':t['tile_id'],'interactions':rows})
(B/'interactions.json').write_text(json.dumps(out,indent=2)+'\n')
